#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> destino: $DEST"
echo "" | base64 -d > "$DEST/ecc_codec_mmio.vhd"
echo "" | base64 -d > "$DEST/ecc_regbank_si.vhd"
echo "" | base64 -d > "$DEST/ecc_soc_si.vhd"
echo "" | base64 -d > "$DEST/tb_codec_mmio.vhd"
echo "" | base64 -d > "$DEST/tb_si_scrub.vhd"
echo "" | base64 -d > "$DEST/gen_si_trace.py"
echo "" | base64 -d > "$DEST/smoke_si.s"
echo "" | base64 -d > "$DEST/tb_smoke_si.vhd"
echo ">> verificando acelerador de codec MMIO (1504 vectores L1)"
( cd "$DEST" && rm -rf work-obj08.cf && \
  ghdl -a --std=08 ecc_pkg.vhd ecc_codec.vhd ecc_codec_mmio.vhd tb_codec_mmio.vhd 2>/dev/null && \
  ghdl -r --std=08 tb_codec_mmio --stop-time=3ms 2>&1 | grep -oE "CODEC_MMIO (PASS|FAIL)" )
echo ">> verificando scrubber por MMIO en regbank de silicio (offsets 0x40+)"
( cd "$DEST" && python3 gen_si_trace.py >/dev/null && rm -rf work-obj08.cf && \
  ghdl -a --std=08 ecc_pkg.vhd ecc_codec.vhd ecc_codec_mmio.vhd scrub_bram.vhd scrub_fsm.vhd ecc_regbank_si.vhd tb_si_scrub.vhd 2>/dev/null && \
  ghdl -r --std=08 tb_si_scrub --stop-time=100us 2>&1 | grep -oE "SILICON SCRUB MMIO (PASS|FAIL)" )
echo ">> smoke del SoC de silicio (arranque + MMIO + doorbell); requiere fuentes RV32+DMA+axil"
( cd "$DEST" && python3 asm.py smoke_si.s smoke_si.mem >/dev/null 2>&1 || python3 "$HOME/rv32i/asm.py" smoke_si.s smoke_si.mem >/dev/null 2>&1; \
  rm -rf work-obj08.cf && \
  ghdl -a --std=08 riscv_pkg.vhd alu.vhd control.vhd immgen.vhd regfile.vhd csr.vhd muldiv.vhd \
    cpu_pipeline.vhd dp_ram.vhd dma_burst.vhd mem_subsys_dma.vhd axil_soc.vhd ecc_pkg.vhd ecc_codec.vhd \
    ecc_codec_mmio.vhd scrub_bram.vhd scrub_fsm.vhd ecc_regbank_si.vhd ecc_soc_si.vhd tb_smoke_si.vhd 2>/dev/null && \
  ghdl -r --std=08 tb_smoke_si --stop-time=5us 2>&1 | grep -oE "smoke_si fin: irq='[01]'" ) || \
  echo "   (si fallo, faltan fuentes RV32/DMA/axil en $DEST)"
